            m_offs = m_start + tl.arange(0, BLOCK_M_INNER)
            m_mask = m_offs < active_rows

            v_vals = tl.load(
                input_ptr
                + bid * stride_ib
                + (ref_idx + m_offs) * stride_im
                + ref_idx * stride_ik,
                mask=(m_offs > 0) & m_mask,
                other=0.0,
            )
