def ormqr(input, tau, other, left=True, transpose=False):
    """
    Computes the matrix-matrix multiplication of a product of Householder matrices
    with a general matrix using Triton kernels.

    Multiplies a m x n matrix C (given by other) with a matrix Q,
    where Q is represented using Householder reflectors (input, tau).

    If left is True then op(Q) @ C is computed, otherwise C @ op(Q).
    If transpose is True then op is the conjugate transpose, otherwise identity.

    Strategy:
    - Small matrices (<=256 in both dims): tiled resident kernel — each program
      owns one column/row tile of C resident on-chip and applies all reflectors
    - Large matrices: tiled streaming kernel with grid over col/row tiles; the
      reflector loop runs inside the kernel (one launch total)

    All computation is in pure Triton kernels. No torch small ops on device data.
    CUDA-graph compatible.

    Args:
        input: tensor of shape (*, mn, k) containing Householder vectors.
        tau: tensor of shape (*, min(mn, k)) containing Householder scalars.
        other: tensor of shape (*, m, n) - the matrix to multiply.
        left: if True, compute op(Q) @ C; otherwise C @ op(Q).
        transpose: if True, op = transpose; otherwise op = identity.

    Returns:
        The result of the matrix multiplication.
    """
    logger.debug("GEMS ORMQR")
    assert input.dtype in (
        torch.float32,
        torch.float64,
    ), f"ormqr only supports float32 and float64, got {input.dtype}"

    # Make contiguous output copy
    C = other.clone().contiguous()
    input_c = input.contiguous()
    tau_c = tau.contiguous()

    # Unified 2D/3D handling via strides
    if C.dim() > 2:
        batch_shape = C.shape[:-2]
        M, N = C.shape[-2], C.shape[-1]
        k = tau_c.shape[-1]
        B = 1
        for s in batch_shape:
            B *= s
        C_flat = C.reshape(B, M, N)
        input_flat = input_c.reshape(B, *input_c.shape[-2:])
        tau_flat = tau_c.reshape(B, k)
        stride_cb = C_flat.stride(0)
        stride_cm = C_flat.stride(1)
        stride_cn = C_flat.stride(2)
        stride_ib = input_flat.stride(0)
        stride_im = input_flat.stride(1)
        stride_ik = input_flat.stride(2)
        stride_tb = tau_flat.stride(0)
    else:
        M, N = C.shape
        k = tau_c.shape[0]
        B = 1
        C_flat = C.unsqueeze(0)
        input_flat = input_c.unsqueeze(0)
        tau_flat = tau_c.unsqueeze(0)
        # batch_stride = 0 means all batch elements point to same data
        # but since B=1 it doesn't matter; use real strides
        stride_cb = 0
        stride_cm = C.stride(0)
        stride_cn = C.stride(1)
        stride_ib = 0
        stride_im = input_c.stride(0)
        stride_ik = input_c.stride(1)
        stride_tb = 0

    # Determine reflector iteration order
    # Q = H_0 H_1 ... H_{k-1}, Q^T = H_{k-1} ... H_0
    # Left Q^T @ C (transpose=True): apply H_0..H_{k-1} forward
    # Left Q @ C (transpose=False): apply H_{k-1}..H_0 reverse
    # Right C @ Q (transpose=False): apply H_0..H_{k-1} forward
    # Right C @ Q^T (transpose=True): apply H_{k-1}..H_0 reverse
    if left:
        reverse = not transpose
    else:
        reverse = transpose

    if left:
        _apply_left(
            C_flat,
            input_flat,
            tau_flat,
            M,
            N,
            k,
            B,
            reverse,
            stride_cb,
            stride_cm,
            stride_cn,
            stride_ib,
            stride_im,
            stride_ik,
            stride_tb,
        )
    else:
        _apply_right(
            C_flat,
            input_flat,
            tau_flat,
            M,
            N,
            k,
            B,
            reverse,
            stride_cb,
            stride_cm,
            stride_cn,
            stride_ib,
            stride_im,
            stride_ik,
            stride_tb,
        )

    return C


def _apply_left(
    C,
    input_t,
    tau_t,
    M,
    N,
    k,
    B,
    reverse,
    stride_cb,
    stride_cm,
    stride_cn,
    stride_ib,
    stride_im,
    stride_ik,
    stride_tb,
):
    """Apply all Householder reflectors from the left in ONE kernel launch."""
    # Decide resident vs streaming path. The resident path needs the whole
    # BLOCK_M-tall tile of C on-chip: BLOCK_M * BLOCK_N * 4B <= ~256KB on
    # gcu400 (DSM budget 448KB incl. intermediates), i.e. M <= 256.
    use_small = M <= 256 and N <= 256

    if use_small:
        BLOCK_M = triton.next_power_of_2(M)
        BLOCK_N = min(triton.next_power_of_2(N), 64)
        num_col_tiles = triton.cdiv(N, BLOCK_N)
        grid = (num_col_tiles, B)
        _householder_left_fused_kernel[grid](
            C,
            input_t,
            tau_t,
            M,
            N,
            k,
            stride_cb,
            stride_cm,
            stride_cn,
            stride_ib,
            stride_im,
            stride_ik,
            stride_tb,
            BLOCK_M=BLOCK_M,
            BLOCK_N=BLOCK_N,
            REVERSE=reverse,
        )
    else:
        # Streaming path. Choose parallelism vs chunk size by tile count:
        # - few tiles (grid <= 16): BLOCK_M_INNER=256 halves the row-chunk
        #   loop length (~1.4-1.6x on 512^2..2048^2)
        # - many tiles: BLOCK_N=128 + BLOCK_M_INNER=128 stays within the
        #   448KB per-program DSM budget so the grid keeps 2 programs/SP
        num_col_tiles128 = triton.cdiv(N, 128)
        if num_col_tiles128 <= 8:
            BLOCK_N = 64
        else:
            BLOCK_N = 128
        num_col_tiles = triton.cdiv(N, BLOCK_N)
        if num_col_tiles <= 16:
            BLOCK_M_INNER = 256
        else:
            BLOCK_M_INNER = 128
        grid = (num_col_tiles, B)
        _householder_apply_left_kernel[grid](
            C,
            input_t,
            tau_t,
            M,
            N,
            k,
            stride_cb,
            stride_cm,
            stride_cn,
            stride_ib,
            stride_im,
            stride_ik,
            stride_tb,
            BLOCK_N=BLOCK_N,
            BLOCK_M_INNER=BLOCK_M_INNER,
            REVERSE=reverse,
        )


def _apply_right(
    C,
    input_t,
    tau_t,
    M,
    N,
    k,
    B,
    reverse,
    stride_cb,
    stride_cm,
    stride_cn,
    stride_ib,
    stride_im,
    stride_ik,
    stride_tb,
):
    """Apply all Householder reflectors from the right in ONE kernel launch."""
    # The resident tile reduces along BLOCK_N (axis=1); on gcu400 a wide
    # (>128) reduction dimension produces wrong results, so cap N at 128.
    # Rows are the splittable dimension and may go up to 256.
    use_small = M <= 256 and N <= 128

    if use_small:
        BLOCK_N = triton.next_power_of_2(N)
        BLOCK_M = min(triton.next_power_of_2(M), 64)
        num_row_tiles = triton.cdiv(M, BLOCK_M)
        grid = (num_row_tiles, B)
        _householder_right_fused_kernel[grid](
            C,
            input_t,
            tau_t,
            M,
            N,
            k,
            stride_cb,
            stride_cm,
            stride_cn,
            stride_ib,
            stride_im,
            stride_ik,
            stride_tb,
            BLOCK_M=BLOCK_M,
            BLOCK_N=BLOCK_N,
            REVERSE=reverse,
        )
    else:
        # Streaming path. NOTE: BLOCK_N_INNER is the axis=1 reduction chunk;
        # widths > 128 produce wrong results on gcu400, so it stays at 128.
        BLOCK_M = 128
        BLOCK_N_INNER = 128
        num_row_tiles = triton.cdiv(M, BLOCK_M)
        grid = (num_row_tiles, B)
        _householder_apply_right_kernel[grid](
            C,
            input_t,
            tau_t,
            M,
            N,
            k,
            stride_cb,
            stride_cm,
            stride_cn,
            stride_ib,
            stride_im,
            stride_ik,
            stride_tb,
            BLOCK_M=BLOCK_M,
            BLOCK_N_INNER=BLOCK_N_INNER,
            REVERSE=reverse,
        )
